12	/// Layout the stack.
13	#[typst_macros::time(span = elem.span())]
14	pub fn layout_stack(
15	    elem: &Packed<StackElem>,
16	    engine: &mut Engine,
17	    locator: Locator,
18	    styles: StyleChain,
19	    regions: Regions,
20	) -> SourceResult<Fragment> {
21	    layout_stack_internal::<fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>>(
22	        elem.children.iter().map(From::from),
23	        elem.span(),
24	        elem.spacing.get(styles),
25	        elem.dir.get(styles),
26	        engine,
27	        locator,
28	        styles,
29	        regions,
30	    )
31	}
